file.content:
  if (!activeQuote.main_content.trim()) {
    alert("Please provide the main quote content before saving.");
    return;
  }

  if (!activeQuote.id) activeQuote.id = generateHexId("0001");
  if (!activeQuote.date) activeQuote.date = new Date().toISOString().split('T')[0];

  try {
    const res = await fetch(`${API_BASE}/api/quote`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(activeQuote)
    });

    if (res.ok) {
      const data = await res.json();
      fireToast(`✓ Saved Quote #${data.index} to SQLite!`);
      activeQuote.index = data.index + 1;
      activeQuote.id = "";
      activeQuote.main_content = "";
      activeQuote.context = "";
      activeQuote.preference = [];
      document.getElementById('input-main-content').value = "";
      document.getElementById('input-context').value = "";
      renderPrefChips();
      renderLiveJSON();
      fetchBackendData();
      return;
    } else {
      const errData = await res.json().catch(() => ({}));
      fireToast("Server Error: " + (errData.error || res.statusText));
    }
  } catch (err) {
    fireToast("❌ Error: Local Server unreachable.");
  }
}

function clearForm() {
  activeQuote = {
    id: "",
    index: activeQuote.index,
    main_content: "",
    context: "",
    date: "",
    specific_id: null,
    theme_ids: [],
    usage_ids: [],
    preference: [],
    backlinks: []
  };
  document.getElementById('input-main-content').value = "";
  document.getElementById('input-context').value = "";
  document.getElementById('input-date').value = "";
  document.getElementById('input-backlink').value = "";
  renderSpecificBadge(null);
  renderThemeChips();
  renderUsagePills();
  renderPrefChips();
  renderLiveJSON();
}

// ==============================================================================
// SOFT-CODED TABLE STUDIO ENGINE (TABLES 1, 2, 3, 4, 5)
// ==============================================================================

let currentTableKey = "quotes";

const TABLES_CONFIG = {
  quotes: {
    id: "quotes",
    title: "Quotes (Table 1: 0001...)",
    desc: "Wisdom passages, reflections, and quotes in SQLite",
    prefix: "0001",
    saveEndpoint: `${API_BASE}/api/quote`,
    deleteEndpoint: `${API_BASE}/api/quote/delete`,
    getData: () => allQuotesList,
