  font-style: normal !important;
  font-weight: 400;
  font-size: 1.6em;
  line-height: 0;
  display: inline-block;
  user-select: none;
  transition: all 0.15s ease;
}
.ep-qmark-open {
  margin-right: 0.35rem;
  vertical-align: -0.1em;
}
.ep-qmark-close {
  margin-left: 0.35rem;
  vertical-align: -0.22em;
}

