             "COALESCE(s.name, '') AS specific_name, "
             "COALESCE(c.name, '') AS container_name, "
             "COALESCE((SELECT GROUP_CONCAT(t.name, ', ') FROM themes t WHERE t.id IN (SELECT value FROM json_each(q.theme_ids))), '') AS theme_names "
