/* ==========================================================================
   E-PAPER HARDWARE CHASSIS — 3-COLOR SYSTEM ARCHITECTURE
   ========================================================================== */
.epaper-chassis {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  border-radius: 12px;
  padding: 2.25rem 2.5rem;
  position: relative;
  transition: all 0.2s ease;
  font-feature-settings: "liga" 0;
  background: var(--ep-bg) !important;
  color: var(--ep-text) !important;
  border: 8px solid var(--ep-border);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.9), 0 0 0 1px var(--ep-border);
}

/* --- PALETTE 1: BLUE (Black-ish + Crisp White + Sapphire/Sky Blue) --- */
.epaper-chassis.palette-blue {
  --ep-bg: #07090e;
  --ep-border: #162032;
  --ep-text: #ffffff;
  --ep-accent: #38bdf8;
  --ep-accent-glow: rgba(56, 189, 248, 0.25);
  --ep-dim: #64748b;
  --ep-tag-bg: #0b1322;
  --ep-tag-border: #1e3a5f;
  --ep-tag-text: #7dd3fc;
  --ep-qmark: #38bdf8;
}

/* --- PALETTE 2: GOLD (Black-ish + Crisp White + Imperial Warm Gold) --- */
.epaper-chassis.palette-gold {
  --ep-bg: #080705;
  --ep-border: #2a2214;
  --ep-text: #ffffff;
  --ep-accent: #f59e0b;
  --ep-accent-glow: rgba(245, 158, 11, 0.25);
  --ep-dim: #78716c;
  --ep-tag-bg: #14120a;
  --ep-tag-border: #3d3419;
  --ep-tag-text: #fcd34d;
  --ep-qmark: #f59e0b;
}

/* --- PALETTE 3: MONO SLATE (Pure Inverted B/W) --- */
.epaper-chassis.palette-mono {
  --ep-bg: #000000;
  --ep-border: #222222;
  --ep-text: #ffffff;
  --ep-accent: #ffffff;
  --ep-accent-glow: transparent;
  --ep-dim: #555555;
  --ep-tag-bg: #111111;
  --ep-tag-border: #222222;
  --ep-tag-text: #777777;
  --ep-qmark: #555555;
}

/* Standard E-Paper Mode (Light Paper Base) Override */
.epaper-chassis:not(.inverted).palette-blue {
  --ep-bg: #eff6ff;
  --ep-border: #bfdbfe;
  --ep-text: #0f172a;
  --ep-accent: #0284c7;
