const idxColor = accentTargets.idx ? 'var(--ep-accent)' : 'var(--ep-text)';
const specificColor = accentTargets.specific ? 'var(--ep-accent)' : 'var(--ep-text)';
const dateColor = accentTargets.date ? 'var(--ep-accent)' : 'var(--ep-text)';
const containerColor = accentTargets.container ? 'var(--ep-accent)' : 'var(--ep-text)';
const qmarkColor = accentTargets.qmark ? 'var(--ep-qmark)' : (currentMarkStyle === 'ghost' ? '#555555' : 'var(--ep-text)');
const dividerBorder = accentTargets.borders ? 'border-color:var(--ep-accent) !important;' : '';

// Content: Italic and wrapped by distinct framing quotation marks
const formattedContent = `<span class="ep-qmark ep-qmark-open" style="color:${qmarkColor} !important;">“</span><em>${b.content.replace(/\n/g, '<br>')}</em><span class="ep-qmark ep-qmark-close" style="color:${qmarkColor} !important;">”</span>`;

// Header components: #<idx> ~ <specific> on left, Date: <date> on right
const headerTitleHTML = `<strong class="ep-idx-num" style="color:${idxColor};">#${b.idx}</strong><span class="ep-sep">~</span><span class="ep-specific-title" style="color:${specificColor};">${b.specificName}</span>`;
const headerDateHTML = `<span class="ep-date-label">Date: </span><span class="ep-date-val" style="color:${dateColor};">${b.effectiveDate}</span>`;

// Footer components: Tags on LEFT (subtle low-contrast blocks), Container on RIGHT
const tagStyle = accentTargets.tags ? '' : 'style="background:#111 !important; border-color:#262626 !important; color:#6a6a6a !important;"';
const tagsBlocks = b.hashtagThemes.map(t => `<span class="ep-tag-block" ${tagStyle}>${t}</span>`).join('');
const containerHTML = `<span class="ep-container-name" style="color:${containerColor};">${b.containerName}</span>`;

if (currentSubLayout === 'minimal') {
  stage.innerHTML = `
    <div class="ep-type-minimal">
      <!-- 1. Header: #<idx> ~ <specific> on left, Date: <date> on right -->
      <div class="ep-status-bar" style="${dividerBorder}">
        <div>${headerTitleHTML}</div>
        <div>${headerDateHTML}</div>
      </div>

      <!-- 2. Content: Category-Driven Alignment -->
      <div class="ep-content ${alignClass}">
        ${formattedContent}
      </div>

      <!-- 3. Optional Context -->
      ${(showContext && b.context) ? `
        <div class="ep-context">
          ${b.context}
        </div>
      ` : ''}

      <!-- 4. Footer: Tags on LEFT · Container on RIGHT -->
      <div class="ep-footer" style="${dividerBorder}">
        <div class="ep-tags">${tagsBlocks}</div>
        <div class="ep-attribution">${containerHTML}</div>
      </div>
    </div>
  `;
} else if (currentSubLayout === 'cardplate') {
  stage.innerHTML = `
    <div class="ep-type-cardplate" style="${dividerBorder}">
      <!-- Header -->
      <div class="ep-card-header" style="${dividerBorder}">
        <div>${headerTitleHTML}</div>
        <div>${headerDateHTML}</div>
      </div>

      <!-- Content -->
      <div class="ep-content ${alignClass}">
        ${formattedContent}
      </div>

      ${(showContext && b.context) ? `
        <div style="font-family:'JetBrains Mono'; font-size:0.8rem; background:var(--ep-tag-bg); padding:0.6rem 0.8rem; border-left:2px solid var(--ep-accent); margin-bottom:1.35rem; line-height:1.5; color:var(--ep-dim);">
          ${b.context}
        </div>
      ` : ''}

      <!-- Footer -->
      <div class="ep-card-footer" style="${dividerBorder}">
        <div class="ep-tags">${tagsBlocks}</div>
        <div class="ep-attribution">${containerHTML}</div>
      </div>
    </div>
  `;
} else if (currentSubLayout === 'poster') {
  stage.innerHTML = `
    <div class="ep-type-poster">
      <div class="ep-idx-huge" style="color:${idxColor};">#${b.idx}</div>

      <div class="ep-status-bar" style="${dividerBorder}">
        <div>${headerTitleHTML}</div>
        <div>${headerDateHTML}</div>
      </div>

      <!-- Content -->
      <div class="ep-content ${alignClass}">
        ${formattedContent}
      </div>

      ${(showContext && b.context) ? `
        <div style="font-family:'JetBrains Mono'; font-size:0.8rem; background:var(--ep-tag-bg); padding:0.6rem 0.8rem; border-left:2px solid var(--ep-accent); margin-bottom:1.35rem; line-height:1.5; color:var(--ep-dim);">
          ${b.context}
        </div>
      ` : ''}

      <!-- Footer -->
      <div class="ep-poster-meta" style="${dividerBorder}">
        <div class="ep-tags">${tagsBlocks}</div>
        <div class="ep-attribution">${containerHTML}</div>
      </div>
    </div>
  `;
}

