</head>
<body>

  <div class=\"container scale-2x\" id=\"app-container\">
    <header class=\"workbench-header\">
      <div class=\"title-area\">
        <h1><span>📟</span> LilyGO T-Display-S3 Simulator</h1>
        <p>Real-Hardware Preview: <strong>1.9\" IPS Bar</strong> · <strong>320 × 170 Pixels</strong> · Board Size: <strong>65 × 28.5 mm</strong></p>
      </div>

      <div class=\"toolbar-row\">
        <select class=\"quote-select\" id=\"quote-select\" onchange=\"loadSelectedQuote(this.value)\">
          <option value=\"\">Loading quotes from SQLite...</option>
        </select>
        <button class=\"ctrl-btn\" onclick=\"pickRandomQuote()\">🎲 Random Quote</button>
        <button class=\"ctrl-btn\" onclick=\"reRollColors()\">🎨 Re-roll Colors</button>
      </div>
    </header>

    <section class=\"scale-strip\">
      <div style=\"display:flex; align-items:center; gap:0.5rem;\">
        <span style=\"color:var(--text-muted); font-weight:700;\">CHASSIS VIEW:</span>
        <div class=\"scale-chips\">
          <button class=\"ctrl-btn\" id=\"btn-scale-1x\" onclick=\"setScaleMode('1x')\">1:1 Real Physical (65mm)</button>
          <button class=\"ctrl-btn active\" id=\"btn-scale-2x\" onclick=\"setScaleMode('2x')\">2:1 Studio Zoom</button>
          <button class=\"ctrl-btn\" id=\"btn-scale-3x\" onclick=\"setScaleMode('3x')\">3:1 Pixel Inspection</button>
        </div>
      </div>

      <div style=\"display:flex; align-items:center; gap:0.6rem;\">
        <span style=\"color:var(--text-muted);\">Accent:</span>
        <span id=\"accent-name-badge\" style=\"color:#38bdf8; font-weight:700;\">Sapphire Blue</span>
        <button class=\"ctrl-btn active\" id=\"btn-toggle-context\" onclick=\"toggleContext()\">Context: ON</button>
      </div>
    </section>

    <main class=\"device-stage\">
      <div class=\"lilygo-pcb\">
        <span class=\"pcb-silkscreen\">LILYGO® T-DISPLAY-S3 // ESP32-S3 // 1.9\" IPS 320x170</span>
        <div class=\"pcb-usbc\" title=\"USB-C 5V / Programming Port\"></div>

        <div class=\"screen-bezel\">
          <div class=\"virtual-lcd-canvas\" id=\"lcd-framebuffer\">
            <!-- Rendered dynamically -->
          </div>
        </div>
      </div>
    </main>

    <section class=\"payload-card\">
      <div style=\"display:flex; justify-content:space-between; align-items:baseline; margin-bottom:0.75rem;\">
        <h3 style=\"font-size:0.85rem; font-weight:700; color:#fff; font-family:'JetBrains Mono';\">
          📡 Turso Cloud JSON Packet Received by ESP32 (320×170 Framebuffer)
        </h3>
        <span style=\"font-size:0.75rem; color:var(--text-muted);\">Format: 5-Point Minimal Metadata</span>
      </div>
      <pre id=\"raw-payload-json\" style=\"font-family:'JetBrains Mono'; font-size:0.76rem; color:#38bdf8; overflow-x:auto; line-height:1.45;\"></pre>
    </section>
  </div>

  <script>
    const API_BASE = window.location.origin.startsWith('http') ? window.location.origin : 'http://127.0.0.1:20137';
    let quotesList = [];
    let activeQuote = null;
    let availableSpecifics = [];
    let availableThemes = [];

    let showContext = true;
    let reRollSeed = 0;
    let currentScale = '2x';

    const ACCENT_POOL = [
      { name: 'Sapphire Blue', hex: '#38bdf8' },
      { name: 'Imperial Gold', hex: '#f59e0b' }
    ];

    function generateVastTagStyle(tagName, tagIndex) {
      let hash = 0;
      for (let i = 0; i < tagName.length; i++) {
        hash = ((hash << 5) - hash) + tagName.charCodeAt(i);
        hash |= 0;
      }
      const goldenAngle = 137.508;
      const hue = Math.abs(Math.floor((hash * goldenAngle + tagIndex * 89 + reRollSeed) % 360));

      const textColor   = 'hsl(' + hue + ', 85%, 74%)';
      const borderColor = 'hsla(' + hue + ', 70%, 40%, 0.45)';
      const bgColor     = 'hsla(' + hue + ', 65%, 8%, 0.95)';
      return 'background: ' + bgColor + ' !important; border-color: ' + borderColor + ' !important; color: ' + textColor + ' !important;';
    }

    async function init() {
      try {
        const [taxRes, qRes] = await Promise.all([
          fetch(API_BASE + '/api/taxonomy').then(r => r.json()).catch(() => ({})),
          fetch(API_BASE + '/api/quotes/list').then(r => r.json()).catch(() => [])
        ]);

        availableSpecifics = taxRes.specifics || [];
        availableThemes = taxRes.themes || [];
        quotesList = qRes || [];

        populateSelect();

        const target = quotesList.find(q => q.idx === 6) || quotesList[0];
        if (target) loadSelectedQuote(target.id);
      } catch (err) {
        document.getElementById('lcd-framebuffer').innerHTML = '<div style=\"padding:1rem; font-size:9px; color:#f43f5e; text-align:center;\">Failed to connect to local server at ' + API_BASE + '.</div>';
      }
    }

    function populateSelect() {
      const select = document.getElementById('quote-select');
      if (quotesList.length === 0) {
        select.innerHTML = '<option>No quotes in database</option>';
        return;
      }
      select.innerHTML = quotesList.map(q => {
        const snippet = q.main_content.split('\\n')[0].substring(0, 32);
        return '<option value=\"' + q.id + '\">#' + (q.idx || q.index) + ' — \"' + snippet + '...\"</option>';
      }).join('');
    }

    function loadSelectedQuote(qid) {
      activeQuote = quotesList.find(q => q.id === qid) || quotesList[0];
      if (!activeQuote) return;
      document.getElementById('quote-select').value = activeQuote.id;
      renderLCDFramebuffer();
    }

    function pickRandomQuote() {
      if (quotesList.length === 0) return;
      const rnd = quotesList[Math.floor(Math.random() * quotesList.length)];
      loadSelectedQuote(rnd.id);
    }

    function reRollColors() {
      reRollSeed = Math.floor(Math.random() * 1000);
      renderLCDFramebuffer();
    }

    function setScaleMode(scale) {
      currentScale = scale;
      const container = document.getElementById('app-container');
      container.classList.remove('scale-1x', 'scale-2x', 'scale-3x');
      container.classList.add('scale-' + scale);

      document.querySelectorAll('[id^=\"btn-scale-\"]').forEach(b => b.classList.remove('active'));
      const activeBtn = document.getElementById('btn-scale-' + scale);
      if (activeBtn) activeBtn.classList.add('active');
    }

    function toggleContext() {
      showContext = !showContext;
      const btn = document.getElementById('btn-toggle-context');
      btn.textContent = 'Context: ' + (showContext ? 'ON' : 'OFF');
      btn.classList.toggle('active', showContext);
      renderLCDFramebuffer();
    }

    function getBundle(q) {
      if (!q) return null;
      const content = q.main_content || '';
      const context = q.context || '';
      const specific = availableSpecifics.find(s => s.id === q.specific_id);
      const specificName = specific ? specific.name : '—';
      const containerName = specific && specific.container ? specific.container.name : (specific ? (specific.container_name || '—') : '—');

      let effectiveDate = (q.date || '').trim();
      let isFallback = false;
      if (!effectiveDate && specific && specific.date && specific.date.trim()) {
        effectiveDate = specific.date.trim();
        isFallback = true;
      }

      const rawThemes = (q.theme_ids || []).map(tid => {
        const th = availableThemes.find(t => t.id === tid);
        return th ? th.name : tid;
      });
      const hashtagThemes = rawThemes.map(t => '#' + t);
      const rawCategory = specific ? (specific.category || '').trim() : '';

      return {
        idx: q.idx || q.index,
        content,
        context,
        category: rawCategory,
        specificName,
        containerName,
        effectiveDate: effectiveDate || '—',
        isFallback,
        hashtagThemes: hashtagThemes.length > 0 ? hashtagThemes : ['#Wisdom']
      };
    }

    function renderLCDFramebuffer() {
      const b = getBundle(activeQuote);
      if (!b) return;

      document.getElementById('raw-payload-json').textContent = JSON.stringify(b, null, 2);
      const fb = document.getElementById('lcd-framebuffer');

      const catLower = (b.category || '').toLowerCase().trim();
      const isWriting = catLower === 'writing' || catLower === 'bài viết' || catLower === 'baiviet';
      const alignClass = isWriting ? 'content-justify' : 'content-left';

      const quoteSeed = (typeof b.idx === 'number' ? b.idx : (parseInt(String(b.idx).replace(/\\D/g, ''), 10) || 1)) + reRollSeed;
      const accentIndex = Math.abs(quoteSeed % ACCENT_POOL.length);
      const activeAccent = ACCENT_POOL[accentIndex];
      const sharedAccentColor = activeAccent.hex;

      const badge = document.getElementById('accent-name-badge');
      badge.textContent = activeAccent.name;
      badge.style.color = sharedAccentColor;

      const formattedContent = '<span class=\"lcd-qmark\" style=\"color:' + sharedAccentColor + ';\">“</span>' + b.content.replace(/\\n/g, '<br>') + '<span class=\"lcd-qmark\" style=\"color:' + sharedAccentColor + ';\">”</span>';

      const headerTitleHTML = '<span class=\"lcd-header-left\"><span class=\"lcd-idx\">#' + b.idx + '</span><span style=\"opacity:0.35;\">~</span><span class=\"lcd-specific\">' + b.specificName + '</span></span>';
      const headerDateHTML = '<span class=\"lcd-date\">Date: ' + b.effectiveDate + '</span>';

      const tagsBlocks = b.hashtagThemes.map((t, idx) => {
        const tagStyle = generateVastTagStyle(t, idx);
        return '<span class=\"lcd-tag-capsule\" style=\"' + tagStyle + '\">' + t + '</span>';
      }).join('');

      const containerHTML = '<span class=\"lcd-container\" style=\"color:' + sharedAccentColor + ';\">' + b.containerName + '</span>';

      fb.innerHTML = `
        <div class=\"lcd-header\">
          <div>${headerTitleHTML}</div>
          <div>${headerDateHTML}</div>
        </div>

        <div class=\"lcd-body\">
          <div class=\"lcd-content ${alignClass}\">
            ${formattedContent}
          </div>

          ${(showContext && b.context) ? `
            <div class=\"lcd-context\">
              [CONTEXT]: ${b.context}
            </div>
          ` : ''}
        </div>

        <div class=\"lcd-footer\">
          <div class=\"lcd-tags-cluster\">${tagsBlocks}</div>
          <div>${containerHTML}</div>
        </div>
      `;
    }

    window.addEventListener('DOMContentLoaded', init);
  </script>
</body>
</html>'''

