      width: 100%;
      background: var(--bg-panel);
      border: 1px solid var(--border-panel);
      border-radius: 8px;
      padding: 0.85rem 1.15rem;
    }
  </style>
</head>
<body>

  <div class="container">
    <!-- Top Header Navigation -->
    <header class="top-bar">
      <div class="title-area">
        <h1><span>🖥️</span> Horizontal Mini-Monitor Simulator</h1>
        <p>Landscape Widescreen PC-Monitor Orientation (Width &gt;&gt; Height) · 1.9" IPS Bar Mode</p>
      </div>

      <div class="toolbar-row">
        <select class="quote-select" id="quote-select" onchange="loadSelectedQuote(this.value)">
          <option value="">Loading quotes from SQLite...</option>
        </select>
        <button class="btn" onclick="pickRandomQuote()">🎲 Random Quote</button>
        <button class="btn" onclick="reRollColors()">🎨 Re-roll Colors</button>
      </div>
    </header>

    <!-- Sub-Bar: Size View Modes & Settings -->
    <section class="sub-bar">
      <div style="display:flex; align-items:center; gap:0.5rem;">
        <span style="color:var(--text-muted); font-weight:700;">WIDESCREEN VIEW:</span>
        <div style="display:inline-flex; background:#000; border:1px solid var(--border-panel); border-radius:6px; padding:2px; gap:2px;">
          <button class="btn active" id="btn-mode-wide" onclick="setViewMode('wide')">Widescreen PC (720×340)</button>
          <button class="btn" id="btn-mode-compact" onclick="setViewMode('compact')">Compact Landscape (580×280)</button>
          <button class="btn" id="btn-mode-1x" onclick="setViewMode('1x')">1:1 Physical LCD (320×170)</button>
        </div>
      </div>

      <div style="display:flex; align-items:center; gap:0.6rem;">
        <span style="color:var(--text-muted);">Quotes &amp; Container:</span>
        <span class="info-pill" id="accent-name-badge" style="color:#38bdf8;">Sapphire Blue</span>
        <button class="btn" id="btn-toggle-context" onclick="toggleContext()">Context: ON</button>
      </div>
    </section>

    <!-- HORIZONTAL MONITOR CHASSIS (PC MONITOR DESK SIMULATOR) -->
    <main class="monitor-chassis view-wide" id="monitor-stage">
      <!-- 16:9 Landscape Screen Frame -->
      <div class="monitor-frame">
        <!-- 1. Header (Ghosted metadata) -->
        <div class="ep-status-bar" id="slot-header">
          <!-- Injected via JS -->
        </div>

        <!-- 2. Centered Widescreen Canvas -->
        <div class="screen-center-stage" id="slot-center">
          <!-- Injected via JS -->
        </div>

        <!-- 3. Footer (Tags on Left, Container on Right) -->
        <div class="ep-footer" id="slot-footer">
          <!-- Injected via JS -->
        </div>
      </div>

      <!-- Monitor Desk Stand Elements -->
      <div class="monitor-stand-neck"></div>
      <div class="monitor-stand-base"></div>
    </main>

    <!-- Edge Packet Inspector -->
    <details class="payload-drawer">
      <summary style="font-size:0.78rem; font-weight:700; color:var(--text-muted); cursor:pointer; outline:none;">
        🔍 Inspect Active Quote 5-Point Payload (Turso Cloud Edge)
      </summary>
      <pre id="raw-payload-json" style="font-family:'JetBrains Mono'; font-size:0.75rem; color:#38bdf8; margin-top:0.75rem; overflow-x:auto; line-height:1.45;"></pre>
    </details>
  </div>

  <script>
    const API_BASE = window.location.origin.startsWith("http") ? window.location.origin : "http://127.0.0.1:20137";
    let quotesList = [];
    let activeQuote = null;
    let availableSpecifics = [];
    let availableThemes = [];

    let showContext = true;
    let reRollSeed = 0;
    let currentViewMode = "wide"; // "wide" | "compact" | "1x"

    // 2-Color Accent Pool for Quotation Marks & Container Name
    const ACCENT_POOL = [
      { name: "Sapphire Blue", hex: "#38bdf8" },
      { name: "Imperial Gold", hex: "#f59e0b" }
    ];

    // Vast Independent Color Palette for Tags (Golden-Ratio Spectrum Engine)
    function generateVastTagStyle(tagName, tagIndex) {
      let hash = 0;
      for (let i = 0; i < tagName.length; i++) {
        hash = ((hash << 5) - hash) + tagName.charCodeAt(i);
        hash |= 0;
      }
      const goldenAngle = 137.508;
      const hue = Math.abs(Math.floor((hash * goldenAngle + tagIndex * 89 + reRollSeed) % 360));

      const textColor   = "hsl(" + hue + ", 85%, 74%)";
      const borderColor = "hsla(" + hue + ", 70%, 40%, 0.45)";
      const bgColor     = "hsla(" + hue + ", 65%, 8%, 0.95)";
      return "background: " + bgColor + " !important; border-color: " + borderColor + " !important; color: " + textColor + " !important;";
    }

    async function init() {
      try {
        const [taxRes, qRes] = await Promise.all([
          fetch(API_BASE + "/api/taxonomy").then(r => r.json()).catch(() => ({})),
          fetch(API_BASE + "/api/quotes/list").then(r => r.json()).catch(() => [])
        ]);

        availableSpecifics = taxRes.specifics || [];
        availableThemes = taxRes.themes || [];
        quotesList = qRes || [];

        populateSelect();

        // Default to Quote #6 (or first available)
        const target = quotesList.find(q => q.idx === 6) || quotesList[0];
        if (target) loadSelectedQuote(target.id);
      } catch (err) {
        document.getElementById("slot-center").innerHTML = "<div style=\"color:#f43f5e; text-align:center;\">Failed to connect to Rose server at " + API_BASE + "</div>";
      }
    }

    function populateSelect() {
      const select = document.getElementById("quote-select");
      if (quotesList.length === 0) {
        select.innerHTML = "<option>No quotes in database</option>";
        return;
      }
      select.innerHTML = quotesList.map(q => {
        const snippet = q.main_content.split("\\n")[0].substring(0, 32);
        return "<option value=\\"" + q.id + "\\">#" + (q.idx || q.index) + " — \\"" + snippet + "...\\"</option>";
      }).join("");
    }

    function loadSelectedQuote(qid) {
      activeQuote = quotesList.find(q => q.id === qid) || quotesList[0];
      if (!activeQuote) return;
      document.getElementById("quote-select").value = activeQuote.id;
      renderHorizontalMonitor();
    }

    function pickRandomQuote() {
      if (quotesList.length === 0) return;
      const rnd = quotesList[Math.floor(Math.random() * quotesList.length)];
      loadSelectedQuote(rnd.id);
    }

    function reRollColors() {
      reRollSeed = Math.floor(Math.random() * 1000);
      renderHorizontalMonitor();
    }

    function setViewMode(mode) {
      currentViewMode = mode;
      const stage = document.getElementById("monitor-stage");
      stage.classList.remove("view-wide", "view-compact", "view-1x");
      stage.classList.add("view-" + mode);

      document.querySelectorAll("[id^=\\"btn-mode-\\"]").forEach(b => b.classList.remove("active"));
      const activeBtn = document.getElementById("btn-mode-" + mode);
      if (activeBtn) activeBtn.classList.add("active");
    }

    function toggleContext() {
      showContext = !showContext;
      const btn = document.getElementById("btn-toggle-context");
      btn.textContent = "Context: " + (showContext ? "ON" : "OFF");
      btn.classList.toggle("active", showContext);
      renderHorizontalMonitor();
    }

    function getBundle(q) {
      if (!q) return null;
      const content = q.main_content || "";
      const context = q.context || "";
      const specific = availableSpecifics.find(s => s.id === q.specific_id);
      const specificName = specific ? specific.name : "—";
      const containerName = specific && specific.container ? specific.container.name : (specific ? (specific.container_name || "—") : "—");

      let effectiveDate = (q.date || "").trim();
      let isFallback = false;
      if (!effectiveDate && specific && specific.date && specific.date.trim()) {
        effectiveDate = specific.date.trim();
        isFallback = true;
      }

      const rawThemes = (q.theme_ids || []).map(tid => {
        const th = availableThemes.find(t => t.id === tid);
        return th ? th.name : tid;
      });
      const hashtagThemes = rawThemes.map(t => "#" + t);
      const rawCategory = specific ? (specific.category || "").trim() : "";

      return {
        idx: q.idx || q.index,
        content,
        context,
        category: rawCategory,
        specificName,
        containerName,
        effectiveDate: effectiveDate || "—",
        isFallback,
        hashtagThemes: hashtagThemes.length > 0 ? hashtagThemes : ["#Wisdom"]
      };
    }

    function renderHorizontalMonitor() {
      const b = getBundle(activeQuote);
      if (!b) return;

      document.getElementById("raw-payload-json").textContent = JSON.stringify(b, null, 2);

      // Category Alignment Rule
      const catLower = (b.category || "").toLowerCase().trim();
      const isWriting = catLower === "writing" || catLower === "bài viết" || catLower === "baiviet";
      const alignClass = isWriting ? "content-justify" : "content-left";

      // Quotation Mark & Container Accent: Random pool of 2 (Gold vs Blue)
      const quoteSeed = (typeof b.idx === "number" ? b.idx : (parseInt(String(b.idx).replace(/\\D/g, ""), 10) || 1)) + reRollSeed;
      const accentIndex = Math.abs(quoteSeed % ACCENT_POOL.length);
      const activeAccent = ACCENT_POOL[accentIndex];
      const sharedAccentColor = activeAccent.hex;

      // Update badge
      const badge = document.getElementById("accent-name-badge");
      badge.textContent = activeAccent.name;
      badge.style.color = sharedAccentColor;

      // 1. Header Elements: #<idx> ~ <specific> on left, Date on right (Ghost gray)
      const headerHTML = `
        <div class="ep-header-left">
          <span class="ep-idx-num">#${b.idx}</span>
          <span class="ep-sep">~</span>
          <span class="ep-specific-title">${b.specificName}</span>
        </div>
        <div class="ep-header-right">
          <span>Date: ${b.effectiveDate}</span>
        </div>
      `;
      document.getElementById("slot-header").innerHTML = headerHTML;

      // 2. Center Content: Italic, framed by quotation marks in shared accent color
      const centerHTML = `
        <div class="lcd-content ${alignClass}">
          <span class="ep-qmark ep-qmark-open" style="color:${sharedAccentColor};">“</span>${b.content.replace(/\\n/g, "<br>")}<span class="ep-qmark ep-qmark-close" style="color:${sharedAccentColor};">”</span>
        </div>
        ${(showContext && b.context) ? `
          <div class="ep-context">
            [${b.context}]
          </div>
        ` : ""}
      `;
      document.getElementById("slot-center").innerHTML = centerHTML;

      // 3. Footer: Tags on Left (Vast random colors), Container on Right (Accent color)
      const tagsBlocks = b.hashtagThemes.map((t, idx) => {
        const tagStyle = generateVastTagStyle(t, idx);
        return `<span class="ep-tag-capsule" style="${tagStyle}">${t}</span>`;
      }).join("");

      const footerHTML = `
        <div class="ep-tags-cluster">${tagsBlocks}</div>
        <div class="ep-container-name" style="color:${sharedAccentColor};">${b.containerName}</div>
      `;
      document.getElementById("slot-footer").innerHTML = footerHTML;
    }

    window.addEventListener("DOMContentLoaded", init);
  </script>
</body>
</html>
"""

