  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">
  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>
  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=IBM+Plex+Serif:ital,wght@0,400;0,600;1,400&display=swap\">
  <style>
    :root {
      --bg-desk:         #070707;
      --bg-panel:        #121212;
      --border-panel:    #242424;
      --text-main:       #dedede;
      --text-muted:      #777777;
      --accent:          #38bdf8;
      font-family: \"JetBrains Mono\", monospace;
      color-scheme: dark;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      background: var(--bg-desk);
      color: var(--text-main);
      padding: 1.5rem 1rem 5rem;
      display: flex;
      flex-direction: column;
      align-items: center;
      min-height: 100vh;
    }

    .container {
      width: 100%;
      max-width: 980px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1.25rem;
    }

    /* Top Header */
    .top-bar {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 0.75rem;
      border-bottom: 1px solid var(--border-panel);
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    .title-group h1 {
      font-size: 1.15rem;
      font-weight: 700;
      color: #ffffff;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .title-group p {
      font-size: 0.76rem;
      color: var(--text-muted);
      margin-top: 0.15rem;
    }

    .toolbar-row {
      display: flex;
      gap: 0.5rem;
      align-items: center;
      flex-wrap: wrap;
    }

    .btn {
      padding: 0.38rem 0.75rem;
      border-radius: 6px;
      border: 1px solid var(--border-panel);
      background: var(--bg-panel);
      color: var(--text-main);
      font-size: 0.78rem;
      font-weight: 600;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      font-family: \"JetBrains Mono\", monospace;
      transition: all 0.12s ease;
    }
    .btn:hover { background: #222222; border-color: #555555; color: #fff; }
    .btn.active { background: #ffffff; color: #000000; border-color: #ffffff; font-weight: 700; }

    select.quote-select {
      padding: 0.38rem 0.75rem;
      border-radius: 6px;
      border: 1px solid var(--border-panel);
      background: var(--bg-panel);
      color: #ffffff;
      font-size: 0.78rem;
      outline: none;
      cursor: pointer;
      font-family: \"JetBrains Mono\", monospace;
      max-width: 260px;
    }

    /* Ratio & Screen Hardware Selector Strip */
    .hardware-bar {
      width: 100%;
      background: var(--bg-panel);
      border: 1px solid var(--border-panel);
      border-radius: 8px;
      padding: 0.75rem 1rem;
      display: flex;
      flex-direction: column;
      gap: 0.65rem;
    }

    .bar-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 0.6rem;
      font-size: 0.76rem;
    }

    .ratio-group {
      display: flex;
      align-items: center;
      gap: 0.45rem;
      flex-wrap: wrap;
    }

    .ratio-btn {
      padding: 0.28rem 0.65rem;
      border-radius: 4px;
      border: 1px solid var(--border-panel);
      background: #000000;
      color: var(--text-muted);
      font-size: 0.75rem;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.12s ease;
      font-family: \"JetBrains Mono\", monospace;
    }
    .ratio-btn:hover { color: #fff; border-color: #555; }
    .ratio-btn.active { background: #ffffff; color: #000000; border-color: #ffffff; font-weight: 700; }

    /* ==========================================================================
       RIEN-PRESCRIPT-BEEPER HARDWARE CHASSIS
       ========================================================================== */
    .beeper-workbench {
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 2.5rem 1rem;
      background: radial-gradient(circle at center, #141414 0%, #050505 100%);
      border: 1px solid var(--border-panel);
      border-radius: 14px;
      width: 100%;
      position: relative;
    }

    /* The Physical Beeper Shell */
    .beeper-shell {
      background: #101010;
      border: 3px solid #282828;
      border-radius: 12px;
      box-shadow: 0 25px 70px rgba(0, 0, 0, 0.95), 0 0 0 1px #333333;
      position: relative;
      padding: 1.5rem 1.75rem 1.25rem;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1.25rem;
      transition: all 0.25s ease;
    }

    /* Beeper Silkscreen Branding */
    .beeper-top-row {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 8px;
      font-weight: 700;
      color: #666666;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 0 2px;
    }

    .beeper-led {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #38bdf8;
      box-shadow: 0 0 8px #38bdf8;
      display: inline-block;
      animation: pulse 2.5s infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 0.8; transform: scale(1); }
      50% { opacity: 0.3; transform: scale(0.85); }
    }

    /* Glass Screen Window */
    .screen-window {
      background: #000000;
      border: 2px solid #1f1f1f;
      border-radius: 6px;
      position: relative;
      box-shadow: inset 0 0 12px rgba(0,0,0,0.9);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      transition: width 0.25s ease, height 0.25s ease;
    }

    /* Subtle Glass Glare */
    .screen-window::after {
      content: \"\";
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: linear-gradient(135deg, rgba(255, 255, 255, 0.03) 0%, transparent 60%);
      pointer-events: none;
    }

    /* Screen Ratio Geometry Configurations */
    /* 1. 1.9\" IPS Bar (320x170 standard landscape, scaled ~2x: 640x340) */
    .screen-ratio-19 {
      width: 640px;
      height: 340px;
      padding: 14px 18px;
    }
    .screen-ratio-19 .content-viewport {
      max-height: 220px;
      font-size: 1.35rem;
      line-height: 1.68;
    }

    /* 2. 2.4\" Classic Pager / Cyberdeck (320x240 4:3, scaled ~2x: 600x450) */
    .screen-ratio-24 {
      width: 600px;
      height: 450px;
      padding: 16px 20px;
    }
    .screen-ratio-24 .content-viewport {
      max-height: 320px;
      font-size: 1.35rem;
      line-height: 1.65;
    }

    /* 3. 2.13\" E-Paper Strip (250x122 2.05:1, scaled ~2.5x: 625x305) */
    .screen-ratio-213 {
      width: 625px;
      height: 305px;
      padding: 12px 16px;
    }
    .screen-ratio-213 .content-viewport {
      max-height: 190px;
      font-size: 1.25rem;
      line-height: 1.6;
    }

    /* 4. 2.9\" Panoramic E-Paper (296x128 2.31:1, scaled ~2.4x: 710x307) */
    .screen-ratio-29 {
      width: 710px;
      height: 307px;
      padding: 12px 18px;
    }
    .screen-ratio-29 .content-viewport {
      max-height: 190px;
      font-size: 1.3rem;
      line-height: 1.6;
    }

    /* 5. 1.69\" Compact Beeper (280x240 7:6, scaled ~2x: 520x445) */
    .screen-ratio-169 {
      width: 520px;
      height: 445px;
      padding: 14px 16px;
    }
    .screen-ratio-169 .content-viewport {
      max-height: 320px;
      font-size: 1.22rem;
      line-height: 1.6;
    }

    /* 6. 1:1 Hardware LCD Pixel Size (Exact 320x170 pixels) */
    .screen-ratio-1x {
      width: 320px;
      height: 170px;
      padding: 7px 9px;
    }
    .screen-ratio-1x .content-viewport {
      max-height: 105px;
      font-size: 10.5px;
      line-height: 1.45;
    }
    .screen-ratio-1x .header-zone,
    .screen-ratio-1x .footer-zone {
      font-size: 7.2px;
    }
    .screen-ratio-1x .ep-qmark {
      font-size: 1.3em;
    }
    .screen-ratio-1x .tag-pill {
      font-size: 6.8px;
      padding: 1px 3px;
    }
    .screen-ratio-1x .context-callout {
      font-size: 6.8px;
      padding: 2px 4px;
    }

    /* ==========================================================================
       SCREEN ZONES (HARDWARE INTERNAL LAYOUT)
       ========================================================================== */
    /* 1. Header: #<idx> ~ <specific> on left ... Date: on right (Ghost gray) */
    .header-zone {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      font-size: 0.74rem;
      font-weight: 500;
      border-bottom: 1px solid #1a1a1a;
      padding-bottom: 4px;
      color: #666666;
      line-height: 1;
      white-space: nowrap;
    }
    .header-left {
      display: flex;
      align-items: baseline;
      gap: 0.35rem;
      max-width: 75%;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .header-idx { color: #777777; font-weight: 700; }
    .header-sep { color: #444444; }
    .header-specific { color: #777777; font-weight: 500; }
    .header-date { color: #666666; font-size: 0.72rem; }

    /* 2. Middle Scrollable Viewport */
    .content-viewport {
      flex: 1;
      overflow-y: auto;
      overflow-x: hidden;
      padding: 0.5rem 0.25rem 0.5rem 0;
      scrollbar-width: thin;
      scrollbar-color: #333333 transparent;
      display: flex;
      flex-direction: column;
      justify-content: flex-start;
      margin: 2px 0;
    }
    .content-viewport::-webkit-scrollbar { width: 4px; }
    .content-viewport::-webkit-scrollbar-thumb { background: #333333; border-radius: 4px; }

    .quote-text {
      font-style: italic;
      color: #ffffff;
      font-weight: 500;
      letter-spacing: -0.01em;
      word-break: break-word;
    }
    .quote-text.align-justify {
      text-align: justify;
      text-justify: inter-word;
    }
    .quote-text.align-left {
      text-align: left;
    }

    /* Architectural Quotation Marks */
    .ep-qmark {
      font-family: Georgia, \"IBM Plex Serif\", serif;
      font-style: normal;
      font-weight: 700;
      font-size: 1.55em;
      line-height: 0;
      display: inline-block;
      user-select: none;
      transition: color 0.15s ease;
    }
    .ep-qmark-open { margin-right: 0.3rem; vertical-align: -0.1em; }
    .ep-qmark-close { margin-left: 0.3rem; vertical-align: -0.22em; }

    /* Context Callout */
    .context-callout {
      font-size: 0.78rem;
      line-height: 1.45;
      color: #666666;
      border-left: 2px solid #333333;
      padding-left: 0.5rem;
      margin-top: 0.65rem;
      background: rgba(255, 255, 255, 0.02);
      padding: 0.35rem 0.5rem;
    }

    /* 3. Footer: Tags on Left ... Container on Right */
    .footer-zone {
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-top: 1px solid #1a1a1a;
      padding-top: 4px;
      font-size: 0.8rem;
      font-weight: 700;
      line-height: 1;
      white-space: nowrap;
    }

    .tags-container {
      display: flex;
      gap: 0.3rem;
      max-width: 65%;
      overflow: hidden;
      flex-wrap: nowrap;
    }

    .tag-pill {
      display: inline-block;
      padding: 0.12rem 0.45rem;
      border-radius: 3px;
      font-size: 0.74rem;
      font-weight: 600;
      letter-spacing: 0.02em;
      line-height: 1.2;
      border: 1px solid transparent;
      white-space: nowrap;
    }

    .container-title {
      font-weight: 700;
      transition: color 0.15s ease;
      text-align: right;
    }

    /* Physical Tactile Beeper Controls on Shell */
    .beeper-controls-bar {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 0.25rem;
      border-top: 1px dashed #222222;
      gap: 0.5rem;
    }

    .beeper-btn {
      padding: 0.35rem 0.65rem;
      border-radius: 4px;
      background: #1c1c1c;
      border: 1px solid #333333;
      color: #aaaaaa;
      font-size: 0.72rem;
      font-weight: 700;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 0.25rem;
      font-family: \"JetBrains Mono\", monospace;
      transition: all 0.12s ease;
      user-select: none;
    }
    .beeper-btn:hover { background: #282828; color: #ffffff; border-color: #555555; }
    .beeper-btn:active { transform: translateY(1px); background: #333333; }
  </style>
</head>
<body>

  <div class=\"container\">
    <!-- Top Bar -->
    <header class=\"top-bar\">
      <div class=\"title-group\">
        <h1><span>📟</span> Rien-Prescript-Beeper Studio</h1>
        <p>Personal Prescripts &amp; Notes Oracle · Scrollable Viewport · Hardware Ratio Playground</p>
      </div>

      <div class=\"toolbar-row\">
        <select class=\"quote-select\" id=\"quote-select\" onchange=\"loadSelectedQuote(this.value)\">
          <option value=\"\">Loading notes from SQLite...</option>
        </select>
        <button class=\"btn\" onclick=\"pickRandomQuote()\">🎲 Random Prescript</button>
        <button class=\"btn\" onclick=\"reRollColors()\">🎨 Re-roll Colors</button>
      </div>
    </header>

    <!-- Hardware Ratio & Display Selector -->
    <section class=\"hardware-bar\">
      <div class=\"bar-row\">
        <div class=\"ratio-group\">
          <span style=\"color:var(--text-muted); font-weight:700;\">SCREEN RATIO:</span>
          <button class=\"ratio-btn active\" id=\"rb-19\" onclick=\"setScreenRatio('19')\">1.9\" IPS Bar (1.88:1 · 320×170)</button>
          <button class=\"ratio-btn\" id=\"rb-24\" onclick=\"setScreenRatio('24')\">2.4\" Pager 4:3 (320×240)</button>
          <button class=\"ratio-btn\" id=\"rb-213\" onclick=\"setScreenRatio('213')\">2.13\" E-Paper (2.05:1 · 250×122)</button>
          <button class=\"ratio-btn\" id=\"rb-29\" onclick=\"setScreenRatio('29')\">2.9\" Panoramic (2.31:1 · 296×128)</button>
          <button class=\"ratio-btn\" id=\"rb-169\" onclick=\"setScreenRatio('169')\">1.69\" Compact 7:6 (280×240)</button>
          <button class=\"ratio-btn\" id=\"rb-1x\" onclick=\"setScreenRatio('1x')\">1:1 Pixel Native (320×170)</button>
        </div>

        <div style=\"display:flex; align-items:center; gap:0.5rem;\">
          <button class=\"btn\" id=\"btn-toggle-context\" onclick=\"toggleContext()\">Context: ON</button>
          <button class=\"btn\" id=\"btn-toggle-autoscroll\" onclick=\"toggleAutoScroll()\">Auto-Scroll: OFF</button>
        </div>
      </div>
    </section>

    <!-- RIEN-PRESCRIPT-BEEPER HARDWARE CHASSIS -->
    <main class=\"beeper-workbench\">
      <div class=\"beeper-shell\">
        <!-- Beeper Top Status & LED -->
        <div class=\"beeper-top-row\">
          <div style=\"display:flex; align-items:center; gap:0.4rem;\">
            <span class=\"beeper-led\"></span>
            <span>RIEN-PRESCRIPT-BEEPER // MODEL 01-A</span>
          </div>
          <span id=\"active-accent-label\" style=\"color:#38bdf8; font-weight:700;\">ACCENT: SAPPHIRE BLUE</span>
        </div>

        <!-- The Physical Glass LCD/E-Paper Window -->
        <div class=\"screen-window screen-ratio-19\" id=\"beeper-screen\">
          <!-- 1. Header Zone -->
          <div class=\"header-zone\" id=\"zone-header\"></div>

          <!-- 2. Scrollable Middle Viewport -->
          <div class=\"content-viewport\" id=\"zone-viewport\"></div>

          <!-- 3. Footer Zone -->
          <div class=\"footer-zone\" id=\"zone-footer\"></div>
        </div>

        <!-- Hardware Tactile Beeper Scroll & Control Buttons -->
        <div class=\"beeper-controls-bar\">
          <div style=\"display:flex; gap:0.35rem;\">
            <button class=\"beeper-btn\" onclick=\"scrollViewport(-60)\">▲ SCROLL UP</button>
            <button class=\"beeper-btn\" onclick=\"scrollViewport(60)\">▼ SCROLL DOWN</button>
          </div>
          <div style=\"font-size:0.7rem; color:#666;\">
            <span>Scroll Wheel &amp; Touch Active</span>
          </div>
          <div style=\"display:flex; gap:0.35rem;\">
            <button class=\"beeper-btn\" onclick=\"pickRandomQuote()\">[NEXT ❯]</button>
          </div>
        </div>
      </div>
    </main>

    <!-- Raw Data Payload Drawer -->
    <details style=\"width:100%; background:var(--bg-panel); border:1px solid var(--border-panel); border-radius:8px; padding:0.85rem 1rem; cursor:pointer;\">
      <summary style=\"font-size:0.8rem; font-weight:700; color:var(--text-muted); outline:none;\">
        🔍 Inspect Turso Cloud 5-Point JSON Payload
      </summary>
      <pre id=\"raw-payload-json\" style=\"font-family:'JetBrains Mono'; font-size:0.76rem; color:#38bdf8; margin-top:0.75rem; overflow-x:auto; line-height:1.45;\"></pre>
    </details>
  </div>

  <script>
    const API_BASE = window.location.origin.startsWith('http') ? window.location.origin : 'http://127.0.0.1:20137';
    let quotesList = [];
    let activeQuote = null;
    let availableSpecifics = [];
    let availableThemes = [];

    let showContext = true;
    let reRollSeed = 0;
    let currentRatio = '19';
    let autoScrollInterval = null;

    // 2-Color Accent Pool for Quote Marks & Container: Gold vs Blue
    const ACCENT_POOL = [
      { name: \"Sapphire Blue\", hex: \"#38bdf8\" },
      { name: \"Imperial Gold\", hex: \"#f59e0b\" }
    ];

    // Vast Independent Color Palette for Tags (Golden-Ratio Spectrum Engine)
    function generateVastTagStyle(tagName, tagIndex) {
      let hash = 0;
      for (let i = 0; i < tagName.length; i++) {
        hash = ((hash << 5) - hash) + tagName.charCodeAt(i);
        hash |= 0;
      }
      const goldenAngle = 137.508;
      const hue = Math.abs(Math.floor((hash * goldenAngle + tagIndex * 89 + reRollSeed) % 360));

      const textColor   = 'hsl(' + hue + ', 85%, 74%)';
      const borderColor = 'hsla(' + hue + ', 70%, 40%, 0.45)';
      const bgColor     = 'hsla(' + hue + ', 65%, 8%, 0.95)';
      return 'background: ' + bgColor + ' !important; border-color: ' + borderColor + ' !important; color: ' + textColor + ' !important;';
    }

    async function init() {
      try {
        const [taxRes, qRes] = await Promise.all([
          fetch(API_BASE + '/api/taxonomy').then(r => r.json()).catch(() => ({})),
          fetch(API_BASE + '/api/quotes/list').then(r => r.json()).catch(() => [])
        ]);

        availableSpecifics = taxRes.specifics || [];
        availableThemes = taxRes.themes || [];
        quotesList = qRes || [];

        populateSelect();

        // Default to Quote #6 (or first available)
        const target = quotesList.find(q => q.idx === 6) || quotesList[0];
        if (target) loadSelectedQuote(target.id);
      } catch (err) {
        document.getElementById('zone-viewport').innerHTML = '<div style=\"padding:1rem; color:#f43f5e; text-align:center;\">Failed to connect to local server at ' + API_BASE + '</div>';
      }
    }

    function populateSelect() {
      const select = document.getElementById('quote-select');
      if (quotesList.length === 0) {
        select.innerHTML = '<option>No notes in database</option>';
        return;
      }
      select.innerHTML = quotesList.map(q => {
        const snippet = q.main_content.split('\\n')[0].substring(0, 30);
        return '<option value=\"' + q.id + '\">#' + (q.idx || q.index) + ' — \"' + snippet + '...\"</option>';
      }).join('');
    }

    function loadSelectedQuote(qid) {
      activeQuote = quotesList.find(q => q.id === qid) || quotesList[0];
      if (!activeQuote) return;

      document.getElementById('quote-select').value = activeQuote.id;
      renderBeeper();
    }

    function pickRandomQuote() {
      if (quotesList.length === 0) return;
      const rnd = quotesList[Math.floor(Math.random() * quotesList.length)];
      loadSelectedQuote(rnd.id);
    }

    function reRollColors() {
      reRollSeed = Math.floor(Math.random() * 1000);
      renderBeeper();
    }

    function setScreenRatio(ratioKey) {
      currentRatio = ratioKey;
      const screen = document.getElementById('beeper-screen');
      screen.className = 'screen-window screen-ratio-' + ratioKey;

      document.querySelectorAll('.ratio-btn').forEach(b => b.classList.remove('active'));
      const activeBtn = document.getElementById('rb-' + ratioKey);
      if (activeBtn) activeBtn.classList.add('active');
    }

    function toggleContext() {
      showContext = !showContext;
      const btn = document.getElementById('btn-toggle-context');
      btn.textContent = 'Context: ' + (showContext ? 'ON' : 'OFF');
      btn.classList.toggle('active', showContext);
      renderBeeper();
    }

    function scrollViewport(offset) {
      const vp = document.getElementById('zone-viewport');
      if (vp) vp.scrollBy({ top: offset, behavior: 'smooth' });
    }

    function toggleAutoScroll() {
      const btn = document.getElementById('btn-toggle-autoscroll');
      if (autoScrollInterval) {
        clearInterval(autoScrollInterval);
        autoScrollInterval = null;
        btn.textContent = 'Auto-Scroll: OFF';
        btn.classList.remove('active');
      } else {
        btn.textContent = 'Auto-Scroll: ON';
        btn.classList.add('active');
        autoScrollInterval = setInterval(() => {
          const vp = document.getElementById('zone-viewport');
          if (vp) {
            if (vp.scrollTop + vp.clientHeight >= vp.scrollHeight - 2) {
              vp.scrollTop = 0;
            } else {
              vp.scrollTop += 1;
            }
          }
        }, 50);
      }
    }

    function getBundle(q) {
      if (!q) return null;
      const content = q.main_content || '';
      const context = q.context || '';
      const specific = availableSpecifics.find(s => s.id === q.specific_id);
      const specificName = specific ? specific.name : '—';
      const containerName = specific && specific.container ? specific.container.name : (specific ? (specific.container_name || '—') : '—');

      let effectiveDate = (q.date || '').trim();
      let isFallback = false;
      if (!effectiveDate && specific && specific.date && specific.date.trim()) {
        effectiveDate = specific.date.trim();
        isFallback = true;
      }

      const rawThemes = (q.theme_ids || []).map(tid => {
        const th = availableThemes.find(t => t.id === tid);
        return th ? th.name : tid;
      });
      const hashtagThemes = rawThemes.map(t => '#' + t);
      const rawCategory = specific ? (specific.category || '').trim() : '';

      return {
        idx: q.idx || q.index,
        content,
        context,
        category: rawCategory,
        specificName,
        containerName,
        effectiveDate: effectiveDate || '—',
        isFallback,
