  font-size: var(--screen-font-size, 13px);
  line-height: 1.52;
  font-style: italic;
  color: #ffffff;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ep-content.content-justify {
