  text-justify: inter-word !important;
  hyphens: auto;
}
.ep-content:not(.animating).content-justify .ep-text-line.line-justify {
  text-align: justify !important;
  text-align-last: justify !important;
  white-space: pre-wrap !important;
}
.ep-content:not(.animating).content-justify .ep-text-line.line-left,
.ep-content.content-left .ep-text-line {
  text-align: left !important;
  text-align-last: left !important;
}
/* Fixed 2D Glyph Matrix during animation (Absolute Zero Jitter) */
.ep-content.animating .ep-text-line {
  white-space: pre !important;
  text-align: left !important;
  text-align-last: left !important;
  word-spacing: normal !important;
  letter-spacing: normal !important;
}

