function entropyStep() {
  if (!isDrawing) return;

  const now = performance.now();
  const elapsed = now - startTime;
  let allLocked = true;

  for (let r = 0; r < MAX_LINES; r++) {
    const rowCells = grid[r];
    const el = document.getElementById(`ptl-${r}`);

    if (!rowCells || rowCells.length === 0) {
      // Blank row: remains completely empty during unboxing placeholder
      if (el) el.innerHTML = '&nbsp;';
      continue;
    }

    let lineHtml = '';
    for (let c = 0; c < rowCells.length; c++) {
      const cell = rowCells[c];

      if (!cell.isLocked) {
        if (elapsed >= cell.lifespanMs) {
          // Lifespan expired: locks into its final character!
          cell.isLocked = true;
          cell.currentChar = cell.targetChar;
        } else {
          allLocked = false;
          if (elapsed >= cell.nextScramble) {
            cell.currentChar = getRandomCipherChar();
            cell.nextScramble = elapsed + 35 + Math.random() * 25;
          }
        }
      }

      if (cell.isLocked) {
        if (cell.targetChar === ' ') {
          lineHtml += `<span class="ep-c ep-space"> </span>`;
        } else if (cell.targetChar === '“' || cell.targetChar === '”') {
          lineHtml += `<span class="ep-c ep-qmark" style="color:${accentColor};">${cell.targetChar}</span>`;
        } else if (cell.targetChar === '.') {
          lineHtml += `<span class="ep-c ep-ellipsis-cue" style="color:${accentColor};">.</span>`;
        } else {
          lineHtml += `<span class="ep-c">${cell.targetChar}</span>`;
        }
      } else {
        lineHtml += `<span class="ep-c ep-scramble">${cell.currentChar}</span>`;
      }
    }

    if (el) {
      el.innerHTML = lineHtml;
    }
  }

  if (now - lastClickTick > 75) {
    playBeeperChirp('click');
    lastClickTick = now;
  }

